// Some portions generated by Claude
import { useCallback, useEffect, useRef, useState } from "react";
import { parseWorkspacePayload, prepareWorkspaceSave, recoveryNotice, saveNotice, type PreparedWorkspaceSave, type WorkspacePayload } from "./workspace.ts";
import {
  discardUnreadableWorkspace,
  loadWorkspaceText,
  openStoredWorkspace,
  recoverUnreadableWorkspace,
  removeEarlierScopes,
  saveWorkspaceText,
} from "./workspace-storage.ts";

/** How soon a change is written to the browser's database (at most once in this time). */
export const AUTOSAVE_MS = 800;
/** The longest wait between a change and its save, however large the graph. */
const MAX_AUTOSAVE_MS = 15_000;

type Options = {
  /** One stored graph per Workbench and repository. */
  scope: string;
  /** The graph as it is now; called when it is saved. */
  snapshot: () => WorkspacePayload;
  /** Values whose change means the graph changed. */
  changes: readonly unknown[];
  /** True while the graph moves (layout animation, dragging): it is saved once it rests. */
  busy: boolean;
  /**
   * Puts a stored graph back, with its graph scope and query, an empty graph's too; called once, when the page opens
   * and a graph is stored. Returns whether it showed it.
   */
  restore: (saved: WorkspacePayload) => boolean;
  /**
   * Replaces the graph with a stored one: newer, saved by another tab (see `checkForNewer`), or recovered (see
   * `recoverUnreadable`). `status` says which.
   */
  replace: (saved: WorkspacePayload, status: string) => void;
  /** Tells the user about saving: storage that is blocked or full, a graph too large to save, or saved in part. */
  notify: (message: string) => void;
};

/**
 * A stored graph the page could not open (it was set aside, see openStoredWorkspace): "recoverable" until a recovery
 * finds nothing in it to read.
 */
export type UnreadableWorkspace = "recoverable" | "unrecoverable" | null;

/**
 * Keeps the graph in the browser (IndexedDB, see workspace-storage.ts): it is read back when the page opens and
 * written shortly after it changes (once it rests), when the tab is hidden and when the page closes. Returns whether
 * the stored graph has been read, so the page does not show its empty state before it knows, and whether a stored
 * graph could not be opened, with the means to recover or discard it.
 */
export function useStoredWorkspace({ scope, snapshot, changes, busy, restore, replace, notify }: Options) {
  const [restored, setRestored] = useState(false);
  const [unreadable, setUnreadable] = useState<UnreadableWorkspace>(null);
  const latest = useRef({ snapshot, restore, replace, notify });
  latest.current = { snapshot, restore, replace, notify };
  /** When the stored graph this tab last read or wrote was saved; a later one was saved by another tab. */
  const knownSavedAt = useRef<string | null>(null);
  const dirty = useRef(false);
  const failed = useRef(false);
  /** The last save was not written: the graph is too large to store. */
  const refused = useRef(false);
  const busyRef = useRef(busy);
  busyRef.current = busy;
  const timer = useRef<number | null>(null);
  const interval = useRef(AUTOSAVE_MS);
  /**
   * True while a stored graph is being shown, its animation included: what that changes is the stored graph itself,
   * not an edit. Saved back, it would be newer than the one stored, and another tab would take it in turn.
   */
  const adopting = useRef(false);

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      const { saved, unreadable } = await openStoredWorkspace(scope);
      if (cancelled) return;
      knownSavedAt.current = saved?.savedAt ?? null;
      if (saved) adopting.current = latest.current.restore(saved);
      setUnreadable(unreadable ? "recoverable" : null);
      setRestored(true);
      void removeEarlierScopes(scope);
    })();
    return () => {
      cancelled = true;
    };
  }, [scope]);

  /** The last thing the user was told about saving: told again only when it changes. */
  const lastNotice = useRef<string | null>(null);
  /** Writes the graph if it changed since it was last written. */
  const save = useRef(() => {});
  save.current = () => {
    if (!dirty.current) return;
    dirty.current = false;
    let prepared: PreparedWorkspaceSave;
    const savedAt = new Date().toISOString();
    const started = performance.now();
    try {
      prepared = prepareWorkspaceSave({ ...latest.current.snapshot(), savedAt });
    } catch {
      return;
    }
    // A save of a large graph takes noticeable time; it then happens less often, at most an eighth of the time.
    interval.current = Math.min(MAX_AUTOSAVE_MS, Math.max(AUTOSAVE_MS, (performance.now() - started) * 8));
    const notice = saveNotice(prepared);
    if (notice !== lastNotice.current) {
      if (notice) latest.current.notify(notice);
      else if (refused.current) latest.current.notify("The graph is saved again.");
    }
    lastNotice.current = notice;
    refused.current = prepared.raw === null;
    // A graph too large to store is not written: the one stored before stays readable.
    if (prepared.raw === null) return;
    knownSavedAt.current = savedAt;
    saveWorkspaceText(prepared.raw, scope).catch(() => {
      if (failed.current) return;
      failed.current = true;
      latest.current.notify("This browser cannot save the graph (its storage is blocked or full), so it is lost when you leave the page.");
    });
  };

  useEffect(() => {
    if (!restored) return;
    const saveNow = () => save.current();
    const saveWhenHidden = () => {
      if (document.visibilityState === "hidden") saveNow();
    };
    document.addEventListener("visibilitychange", saveWhenHidden);
    window.addEventListener("pagehide", saveNow);
    return () => {
      document.removeEventListener("visibilitychange", saveWhenHidden);
      window.removeEventListener("pagehide", saveNow);
      if (timer.current !== null) window.clearTimeout(timer.current);
      timer.current = null;
      saveNow();
    };
  }, [restored]);

  // A throttle, not a debounce: a graph that keeps changing is still written every AUTOSAVE_MS, except while it moves.
  // The state just restored (or the empty start) is not a change; only what happens after it is saved.
  const armed = useRef(false);
  useEffect(() => {
    if (!restored) return;
    if (adopting.current) {
      // The stored graph is shown once it rests: this change is still part of showing it.
      if (!busyRef.current) adopting.current = false;
      armed.current = true;
      return;
    }
    if (!armed.current) {
      armed.current = true;
      return;
    }
    dirty.current = true;
  }, [restored, ...changes]);
  useEffect(() => {
    if (!restored || !dirty.current || timer.current !== null) return;
    const tick = () => {
      timer.current = null;
      if (!dirty.current) return;
      if (busyRef.current) timer.current = window.setTimeout(tick, interval.current);
      else save.current();
    };
    timer.current = window.setTimeout(tick, interval.current);
  }, [restored, busy, ...changes]);

  /**
   * Brings the graph up to date when another tab saved a newer one (a Graph tab coming back into view after the user
   * worked in another). Resolves to whether it replaced the graph.
   */
  const checkForNewer = useCallback(async () => {
    if (!restored || dirty.current) return false;
    let saved: WorkspacePayload | null = null;
    try {
      const raw = await loadWorkspaceText(scope);
      saved = raw ? parseWorkspacePayload(raw, {repositoryReferences: true}) : null;
    } catch {
      return false;
    }
    if (!saved?.savedAt || (knownSavedAt.current !== null && saved.savedAt <= knownSavedAt.current)) return false;
    // An edit made while the stored graph was read is kept, and saved as the newer graph.
    if (dirty.current) return false;
    knownSavedAt.current = saved.savedAt;
    adopting.current = true;
    latest.current.replace(saved, "Updated to the graph saved in another tab.");
    return true;
  }, [restored, scope]);

  /** Replaces the graph shown with what can be read of the stored graph that could not be opened. */
  const recoverUnreadable = useCallback(async () => {
    let recovered: Awaited<ReturnType<typeof recoverUnreadableWorkspace>>;
    try {
      recovered = await recoverUnreadableWorkspace(scope);
    } catch {
      latest.current.notify("The graph could not be recovered: this browser's storage is blocked or full.");
      return;
    }
    if (!recovered) {
      setUnreadable("unrecoverable");
      latest.current.notify("Nothing in the saved graph that could not be opened can be read.");
      return;
    }
    // Saved, it is the stored graph now; one still too large to save stays set aside and is offered again.
    if (recovered.saved) knownSavedAt.current = recovered.payload.savedAt;
    setUnreadable(null);
    latest.current.replace(recovered.payload, recoveryNotice(recovered));
  }, [scope]);

  /** Deletes the stored graph that could not be opened. */
  const discardUnreadable = useCallback(async () => {
    await discardUnreadableWorkspace(scope).catch(() => {});
    setUnreadable(null);
    latest.current.notify("Deleted the saved graph that could not be opened.");
  }, [scope]);

  return { restored, checkForNewer, unreadable, recoverUnreadable, discardUnreadable };
}
